/**
 * @name Environment variable data flowing into OS commands
 * @description Detect flows from os.getenv to os.system/subprocess.* which may indicate command injection risk
 * @kind path-problem
 * @problem.severity warning
 * @id py/envvar-command-injection-colorama
 * @tags security
 *       external/cwe/cwe-078
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.ApiGraphs

module EnvVarCmdConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    exists(API::CallNode getenvCall |
      getenvCall = API::moduleImport("os").getMember("getenv").getACall() and
      source = getenvCall.getArg(0)
    )
  }

  predicate isSink(DataFlow::Node sink) {
    exists(API::CallNode cmdCall |
      (
        cmdCall = API::moduleImport("os").getMember("system").getACall() or
        cmdCall = API::moduleImport("subprocess").getMember(["Popen", "call", "run", "check_call", "check_output"]).getACall()
      ) and
      sink = cmdCall.getArg(0)
    )
  }
}

module EnvVarCmdFlow = TaintTracking::Global<EnvVarCmdConfig>;
import EnvVarCmdFlow::PathGraph

from EnvVarCmdFlow::PathNode source, EnvVarCmdFlow::PathNode sink
where EnvVarCmdFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "Environment-variable-derived data flows into OS command execution $@.", source.getNode(), "env var"
